const fs=require('node:fs'),p=require('node:path'),{createRequire}=require('node:module');
const[beforeFile,afterFile,archive,anchor]=process.argv.slice(2),old=JSON.parse(fs.readFileSync(beforeFile,'utf8')),now=JSON.parse(fs.readFileSync(afterFile,'utf8')),asar=createRequire(p.resolve(anchor))('@electron/asar'),out='comparison-evidence';fs.mkdirSync(out,{recursive:true});
const groups={},added=[],removed=[],changed=[],lineEndingOnly=[],modeChanges=[],packingChanges=[];let same=0;
const group=x=>x.startsWith('dist/')?'desktop':x.startsWith('ui-dist/')?'ui':x.startsWith('node_modules/@sublang/spex-core/')?'core':x.startsWith('node_modules/@sublang/cligent/')?'cligent':x.startsWith('node_modules/@sublang/playbook/')?'playbook':'other';
for(const key of [...new Set([...Object.keys(old.files),...Object.keys(now.files)])].sort()){
 const a=old.files[key],b=now.files[key],g=group(key);groups[g]??={same:0,changed:0,added:0,removed:0,lineEndingOnly:0};
 if(!a){added.push(key);groups[g].added++;continue}if(!b){removed.push(key);groups[g].removed++;continue}
 if(a.sha256===b.sha256&&a.link===b.link){same++;groups[g].same++;}else if(a.lfSha256&&a.lfSha256===b.lfSha256){lineEndingOnly.push(key);groups[g].lineEndingOnly++;}else{changed.push(key);groups[g].changed++;if(b.lfSha256){const file=p.join(out,'new-files',...key.split('/'));fs.mkdirSync(p.dirname(file),{recursive:true});fs.writeFileSync(file,asar.extractFile(archive,key.split('/').join(p.sep)));}}
 if(a.executable!==b.executable)modeChanges.push({file:key,before:a.executable,after:b.executable});if(a.unpacked!==b.unpacked)packingChanges.push({file:key,before:a.unpacked,after:b.unpacked});
}
const packageVersions=[];for(const key of [...new Set([...Object.keys(old.packages),...Object.keys(now.packages)])].sort())if(JSON.stringify(old.packages[key])!==JSON.stringify(now.packages[key]))packageVersions.push({file:key,before:old.packages[key],after:now.packages[key]});
const outsideChanges=[];if(old.outside.electronFramework&&JSON.stringify(old.outside.electronFramework)!==JSON.stringify(now.outside.electronFramework))outsideChanges.push({file:'Electron Framework',before:old.outside.electronFramework,after:now.outside.electronFramework});if(old.outside.electronExecutable){for(const name of Object.keys(old.outside.electronExecutable.sections)){const a=old.outside.electronExecutable.sections[name],b=now.outside.electronExecutable.sections[name];if(JSON.stringify(a)!==JSON.stringify(b))outsideChanges.push({file:'electron.exe section '+name,before:a,after:b});}for(const name of [...new Set([...Object.keys(old.outside.dlls),...Object.keys(now.outside.dlls)])]){const a=old.outside.dlls[name],b=now.outside.dlls[name];if(JSON.stringify(a)!==JSON.stringify(b))outsideChanges.push({file:name,before:a,after:b});}}
const report={status:changed.length||added.length||removed.length||lineEndingOnly.length||outsideChanges.length?'differences_require_review':'identical_payload',before:old.label,after:now.label,platform:now.platform,beforeFiles:old.fileCount,afterFiles:now.fileCount,same,groups,changed,added,removed,lineEndingOnly,modeChanges,packingChanges,packageVersions,outsideChanges};fs.writeFileSync(p.join(out,'comparison.json'),JSON.stringify(report,null,2)+'\n');fs.copyFileSync(afterFile,p.join(out,'new-manifest.json'));fs.copyFileSync('download/installer-proof.json',p.join(out,'installer-proof.json'));console.log(JSON.stringify({status:report.status,platform:report.platform,same,groups,changed:changed.length,added:added.length,removed:removed.length,lineEndingOnly:lineEndingOnly.length,modeChanges:modeChanges.length,packingChanges:packingChanges.length,packageVersions:packageVersions.length,outsideChanges:outsideChanges.map(x=>x.file)}));
